import{_ as t,o as e,c as s,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"28. Att välja och förstå SQL-system","description":"","frontmatter":{},"headers":[],"relativePath":"sv/chapters/28-att-valja-och-forsta-sql-system.md","filePath":"sv/chapters/28-att-valja-och-forsta-sql-system.md"}'),n={name:"sv/chapters/28-att-valja-och-forsta-sql-system.md"};function i(l,a,d,o,k,p){return e(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="_28-att-valja-och-forsta-sql-system" tabindex="-1">28. Att välja och förstå SQL-system <a class="header-anchor" href="#_28-att-valja-och-forsta-sql-system" aria-label="Permalink to &quot;28. Att välja och förstå SQL-system&quot;">​</a></h1><p>Vi har arbetat med SQL som ett språk för att beskriva, hämta och förändra information. Vi har skapat relationer, skrivit Queries och undersökt hur databasen upprätthåller regler och genomför transaktioner.</p><p>Men när vi installerar en databas installerar vi inte bara <em>SQL</em>. Vi väljer ett <strong>databashanteringssystem</strong> – en programvara som tolkar våra SQL-satser, lagrar data och ansvarar för hur de kan användas.</p><p>Det finns många sådana system. De har mycket gemensamt, men skiljer sig åt på sätt som påverkar både våra Queries och hur vi bygger applikationer.</p><p>Hur ska vi förstå skillnaderna utan att förlora det gemensamma?</p><h2 id="grund" tabindex="-1">Grund <a class="header-anchor" href="#grund" aria-label="Permalink to &quot;Grund&quot;">​</a></h2><h3 id="sql-ar-ett-sprak-–-inte-en-databas" tabindex="-1">SQL är ett språk – inte en databas <a class="header-anchor" href="#sql-ar-ett-sprak-–-inte-en-databas" aria-label="Permalink to &quot;SQL är ett språk – inte en databas&quot;">​</a></h3><p><strong>SQL</strong> (<em>Structured Query Language</em>) beskriver hur vi kan arbeta med relationella data.</p><p><strong>MySQL</strong>, <strong>PostgreSQL</strong>, <strong>SQLite</strong> och <strong>Microsoft SQL Server</strong> är exempel på databashanteringssystem som använder SQL.</p><p>Vi kan jämföra skillnaden med ett språk och dess olika användningsmiljöer: två system kan förstå samma grundläggande SQL men ha olika utvidgningar, regler och sätt att arbeta.</p><p>En Query som:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title, price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>fungerar i många SQL-system utan ändringar.</p><p>Men all SQL är inte lika portabel. Vi har redan mött exempel på skillnader i datumfunktioner, JSON-hantering och geografiska funktioner.</p><h3 id="sql-standarden-och-dialekter" tabindex="-1">SQL-standarden och dialekter <a class="header-anchor" href="#sql-standarden-och-dialekter" aria-label="Permalink to &quot;SQL-standarden och dialekter&quot;">​</a></h3><p>SQL har en internationell standard, som utvecklas över tid.</p><p>Standarden beskriver bland annat språkets grundläggande konstruktioner. Men den betyder inte att alla databassystem erbjuder exakt samma funktioner eller tolkar alla situationer på samma sätt.</p><p>En <strong>SQL-dialekt</strong> är ett visst systems sätt att stödja och ibland utöka SQL.</p><p>Vi har exempelvis använt:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OFFSET </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Det här fungerar i MySQL, PostgreSQL och SQLite.</p><p>SQL-standardens sätt att uttrycka ett motsvarande urval kan i stället se ut så här:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OFFSET </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ROWS</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FETCH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NEXT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ROWS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ONLY;</span></span></code></pre></div><p>Men stödet för olika varianter skiljer sig. Därför behöver vi lära oss både <strong>den gemensamma idén</strong> och <strong>den syntax som gäller där vi faktiskt arbetar</strong>.</p><p>Vi bör dessutom ange <code>ORDER BY</code> när urvalet beror på vilka rader som kommer först. Utan uttrycklig sortering finns ingen garanterad ordning.</p><h3 id="fyra-vanliga-sql-system" tabindex="-1">Fyra vanliga SQL-system <a class="header-anchor" href="#fyra-vanliga-sql-system" aria-label="Permalink to &quot;Fyra vanliga SQL-system&quot;">​</a></h3><table tabindex="0"><thead><tr><th>System</th><th>Typisk egenskap</th></tr></thead><tbody><tr><td><strong>MySQL</strong></td><td>Vanligt i webbapplikationer och servermiljöer</td></tr><tr><td><strong>PostgreSQL</strong></td><td>Brett funktionsstöd och många möjligheter till utbyggnad</td></tr><tr><td><strong>SQLite</strong></td><td>Inbyggd databas som ofta används direkt av en applikation</td></tr><tr><td><strong>SQL Server</strong></td><td>Integrerat databassystem med omfattande drift- och administrationsfunktioner</td></tr></tbody></table><p>Det är exempel på användningsområden, <strong>inte begränsningar</strong>. Samma system kan användas i många olika sammanhang.</p><p>I vår bok har vi ofta använt MySQL som praktisk referens. Det innebär inte att MySQL alltid är det lämpligaste valet.</p><h3 id="serverdatabas-eller-inbyggd-databas" tabindex="-1">Serverdatabas eller inbyggd databas <a class="header-anchor" href="#serverdatabas-eller-inbyggd-databas" aria-label="Permalink to &quot;Serverdatabas eller inbyggd databas&quot;">​</a></h3><p>MySQL, PostgreSQL och SQL Server används ofta som <strong>serverbaserade databashanterare</strong>.</p><p>En databasserver kan ta emot anslutningar från flera program och användare. Den ansvarar för bland annat samtidighet, åtkomstkontroll och lagring.</p><p>SQLite används vanligtvis som en <strong>inbyggd databas</strong> i en applikation, där informationen lagras i en lokal databasfil.</p><p>Det betyder inte att SQLite saknar transaktioner eller relationsstöd. Men arkitekturen är annorlunda: vi har normalt ingen separat SQL-serverprocess som programmen ansluter till på samma sätt.</p><p>En lokal mobilapp och en stor webbhandel kan därför ha olika behov, även om de lagrar liknande information.</p><h3 id="skillnader-i-syntax" tabindex="-1">Skillnader i syntax <a class="header-anchor" href="#skillnader-i-syntax" aria-label="Permalink to &quot;Skillnader i syntax&quot;">​</a></h3><p>Tänk att vi vill hämta de fem dyraste produkterna.</p><p>I MySQL, PostgreSQL och SQLite kan vi skriva:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title, price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>I SQL Server kan ett motsvarande exempel använda <code>TOP</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TOP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) title, price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, id;</span></span></code></pre></div><p>Vi försöker beskriva <strong>samma informationsbehov</strong>, men syntaxen skiljer sig.</p><p>Det är därför värdefullt att förstå <code>ORDER BY</code> och begränsning av rader som begrepp, i stället för att bara memorera en dialekts formuleringar.</p><h3 id="datatyper-ar-inte-identiska-overallt" tabindex="-1">Datatyper är inte identiska överallt <a class="header-anchor" href="#datatyper-ar-inte-identiska-overallt" aria-label="Permalink to &quot;Datatyper är inte identiska överallt&quot;">​</a></h3><p>Vi har arbetat med <code>INTEGER</code>, <code>DECIMAL</code>, <code>VARCHAR</code> och <code>DATE</code>.</p><p>De är vanliga datatyper, men detaljerna varierar.</p><p>Exempelvis har SQLite en särskild modell för typaffinitet och dynamisk typning, medan andra system i större utsträckning upprätthåller kolumnens deklarerade datatyp. SQLite kan också använda <code>STRICT</code>-tabeller för striktare typregler.</p><p>Även <code>BOOLEAN</code>, autogenererade identifierare och hur datum och tidszoner lagras skiljer sig mellan systemen.</p><p>Sådana skillnader påverkar inte bara <strong>hur vi skriver SQL</strong>, utan också <strong>vilka garantier vi kan förvänta oss av datamodellen</strong>.</p><h2 id="avancerat" tabindex="-1">Avancerat <a class="header-anchor" href="#avancerat" aria-label="Permalink to &quot;Avancerat&quot;">​</a></h2><h3 id="samma-sql-kan-ge-olika-praktiska-forutsattningar" tabindex="-1">Samma SQL kan ge olika praktiska förutsättningar <a class="header-anchor" href="#samma-sql-kan-ge-olika-praktiska-forutsattningar" aria-label="Permalink to &quot;Samma SQL kan ge olika praktiska förutsättningar&quot;">​</a></h3><p>Att två databassystem accepterar samma Query betyder inte att de genomför den på samma sätt.</p><p>De kan ha olika strategier för index, optimering, transaktioner, låsning och radversionering.</p><p>Exempelvis kan:</p><ul><li>En viss <code>JOIN</code> planeras på olika sätt.</li><li>Ett index byggas och användas annorlunda.</li><li>Två samtidiga transaktioner påverka varandra på olika sätt.</li><li>En schemaändring kräva olika mycket låsning eller driftplanering.</li></ul><p>Därför är en Querys <strong>logiska betydelse</strong> inte samma sak som dess <strong>faktiska exekvering</strong>.</p><p>Vi mötte denna skillnad i kapitlen om transaktioner och Query-prestanda.</p><h3 id="funktioner-som-utokar-sql" tabindex="-1">Funktioner som utökar SQL <a class="header-anchor" href="#funktioner-som-utokar-sql" aria-label="Permalink to &quot;Funktioner som utökar SQL&quot;">​</a></h3><p>Databassystem kan erbjuda funktioner som går utöver den gemensamma SQL-kärnan.</p><p>Vi har redan sett exempel:</p><table tabindex="0"><thead><tr><th>Område</th><th>Exempel på skillnader</th></tr></thead><tbody><tr><td>Datum och tid</td><td><code>DATE_FORMAT()</code> i MySQL, <code>DATE_TRUNC()</code> i PostgreSQL</td></tr><tr><td>JSON</td><td>Olika typer, operatorer och JSON-funktioner</td></tr><tr><td>Geografiska data</td><td>Olika spatiala funktioner och tillägg</td></tr><tr><td>Fulltextsökning</td><td>Olika index, språkstöd och söksyntax</td></tr><tr><td>Programlogik i databasen</td><td>Skillnader i procedurer, funktioner och triggers</td></tr></tbody></table><p>Ett exempel är <strong>PostGIS</strong>, en utvidgning till PostgreSQL med omfattande funktioner för geografiska data.</p><p>Vi ska alltså inte anta att varje SQL-system erbjuder alla tekniker vi sett i boken på exakt samma sätt.</p><h3 id="vad-kan-vi-flytta-mellan-system" tabindex="-1">Vad kan vi flytta mellan system? <a class="header-anchor" href="#vad-kan-vi-flytta-mellan-system" aria-label="Permalink to &quot;Vad kan vi flytta mellan system?&quot;">​</a></h3><p>En grundläggande Query som använder <code>SELECT</code>, <code>WHERE</code> och <code>JOIN</code> kan ofta flyttas ganska enkelt.</p><p>Men en faktisk applikation är beroende av mer än enskilda Queries:</p><ul><li>Datatyper, standardvärden och begränsningar.</li><li>Identifierare och regler för autogenererade nycklar.</li><li>Index, Views och eventuella databasfunktioner.</li><li>Transaktionernas beteende och isoleringsnivåer.</li><li>Behörigheter, användarkonton och roller.</li><li>Drivrutiner, anslutningssträngar och migrationsskript.</li></ul><p>Att byta databashanterare är därför inte alltid bara att ersätta anslutningssträngen.</p><p>Ju mer vi använder ett visst systems specialfunktioner, desto viktigare blir det att förstå hur beroendet påverkar möjligheten att byta system senare.</p><p>Men att undvika <em>alla</em> systemspecifika funktioner kan också innebära att vi avstår från användbara möjligheter. Portabilitet är en avvägning, inte ett självändamål.</p><h3 id="hur-valjer-vi-ett-sql-system" tabindex="-1">Hur väljer vi ett SQL-system? <a class="header-anchor" href="#hur-valjer-vi-ett-sql-system" aria-label="Permalink to &quot;Hur väljer vi ett SQL-system?&quot;">​</a></h3><p>I stället för att fråga vilket system som är <em>bäst</em> kan vi fråga vilka krav vår tillämpning faktiskt har.</p><table tabindex="0"><thead><tr><th>Fråga</th><th>Varför den spelar roll</th></tr></thead><tbody><tr><td>Var ska programmet köras?</td><td>En lokal applikation har andra driftbehov än ett publikt system</td></tr><tr><td>Hur många ska använda det samtidigt?</td><td>Samtidighet, anslutningar och skrivbelastning påverkar arkitekturvalet</td></tr><tr><td>Hur viktig är tillgängligheten?</td><td>Drift, säkerhetskopiering och återställning behöver planeras</td></tr><tr><td>Vilka datatyper och funktioner krävs?</td><td>JSON, geografiska data och andra specialfunktioner kan skilja sig</td></tr><tr><td>Vilken kompetens finns?</td><td>Ett system behöver kunna utvecklas, felsökas och förvaltas</td></tr><tr><td>Vilka tekniska beroenden har vi?</td><td>Drivrutiner, molntjänster och integrationer påverkar valet</td></tr></tbody></table><p>Krav som prestanda, kostnad och skalbarhet behöver bedömas i den <strong>faktiska miljön</strong>, inte enbart utifrån allmänna påståenden om olika produkter.</p><h3 id="ett-exempel-bokhandeln-vaxer" tabindex="-1">Ett exempel: bokhandeln växer <a class="header-anchor" href="#ett-exempel-bokhandeln-vaxer" aria-label="Permalink to &quot;Ett exempel: bokhandeln växer&quot;">​</a></h3><p>Anta att bokhandeln börjar som en liten lokal applikation för att hålla reda på produkter och lager.</p><p>En inbyggd databas som SQLite skulle kunna vara lämplig om allt hanteras i en och samma applikation och miljö.</p><p>När bokhandeln senare får en webbplats, flera butiker och många samtidiga användare kan en serverbaserad databas bli mer praktisk.</p><p>Men det betyder inte att SQLite automatiskt är otillräckligt så snart flera personer använder systemet, eller att en större serverdatabas alltid är bättre. Vi behöver undersöka arkitekturen och hur belastningen faktiskt ser ut.</p><p>Ett sådant byte påverkar också vårt arbetssätt. Vi behöver tänka på migrering av data, testning av Queries, behörigheter och hur programmen ansluter.</p><h3 id="drift-ar-en-del-av-teknikvalet" tabindex="-1">Drift är en del av teknikvalet <a class="header-anchor" href="#drift-ar-en-del-av-teknikvalet" aria-label="Permalink to &quot;Drift är en del av teknikvalet&quot;">​</a></h3><p>Två system kan vara likvärdiga för de Queries vi skriver men ställa olika krav på drift.</p><p>Vi behöver ta ställning till exempelvis:</p><ul><li>Säkerhetskopiering och återställning.</li><li>Övervakning, loggar och larm.</li><li>Uppgraderingar och säkerhetsuppdateringar.</li><li>Replikering och hantering av driftavbrott.</li><li>Ansvar för servermiljö, åtkomst och tillgänglighet.</li></ul><p>Det finns också hanterade databastjänster där en leverantör tar ansvar för delar av driften.</p><p>Det avlägsnar inte vårt ansvar för datamodell, behörigheter, kvalitetsregler och hur applikationen använder informationen.</p><h3 id="standardisering-och-sjalvstandighet" tabindex="-1">Standardisering och självständighet <a class="header-anchor" href="#standardisering-och-sjalvstandighet" aria-label="Permalink to &quot;Standardisering och självständighet&quot;">​</a></h3><p>En fördel med ett standardiserat språk är att vi kan ta med oss mycket av vår kunskap mellan olika system.</p><p>Men <strong>standardisering av språk</strong> är inte samma sak som <strong>oberoende av teknikleverantörer</strong>.</p><p>Vi kan använda SQL och ändå vara beroende av ett visst systems funktioner, verktyg eller driftsmiljö.</p><p>För vissa verksamheter är det viktigt att kunna flytta data och applikationer mellan miljöer. För andra väger integration, prestanda eller tillgång till viss funktionalitet tyngre.</p><p>Vi behöver därför kunna skilja mellan:</p><p><strong>Öppna principer</strong> – idéer och standarder som kan användas i flera system.</p><p><strong>Systemspecifika möjligheter</strong> – funktioner som gör ett visst system särskilt användbart.</p><p><strong>Praktisk flyttbarhet</strong> – vad vi faktiskt kan överföra utan stora förändringar.</p><p>Det är tre relaterade men inte identiska saker.</p><h3 id="att-valja-ett-system-ar-att-valja-forutsattningar" tabindex="-1">Att välja ett system är att välja förutsättningar <a class="header-anchor" href="#att-valja-ett-system-ar-att-valja-forutsattningar" aria-label="Permalink to &quot;Att välja ett system är att välja förutsättningar&quot;">​</a></h3><p>En databashanterare bestämmer inte vad en kund, produkt eller beställning betyder. Det är vårt arbete att modellera.</p><p>Men vårt val av databashanterare påverkar <strong>hur modellen kan uttryckas, vilka regler som kan upprätthållas och vilka verktyg vi har för att arbeta med informationen</strong>.</p><p>Det betyder att teknikvalet varken bör göras enbart utifrån favoritprodukter eller enbart utifrån en lista över SQL-funktioner.</p><p>Vi behöver förstå informationsbehovet, verksamhetens utveckling och vilka förutsättningar som måste finnas för att informationen ska förbli användbar över tid.</p><h2 id="reflektion" tabindex="-1">Reflektion <a class="header-anchor" href="#reflektion" aria-label="Permalink to &quot;Reflektion&quot;">​</a></h2><ol><li>Varför kan två databashanterare som båda använder SQL ändå kräva olika lösningar för samma applikation?</li><li>När är det rimligt att använda en systemspecifik funktion även om den gör det svårare att byta databashanterare?</li><li>Varför räcker det inte att jämföra SQL-syntax när vi ska välja vilket databassystem en verksamhet behöver?</li></ol>`,103)])])}const m=t(n,[["render",i]]);export{g as __pageData,m as default};
